mkdir -p "$CLOSED"
{ grep '^#' "$LEDGER"; awk -F'\t' -v p="$m" '!/^#/ && NF && index($1, p) == 1' "$LEDGER"; } > "$CLOSED/$m.tsv"
echo "closed $m: $(grep -vc '^#' "$CLOSED/$m.tsv") row(s) -> $CLOSED/$m.tsv"

